// taken from https://github.com/ksykulev/objektivity/blob/master/objektivity.js
Skizeit.Utils.objectify = (function () {
  var DEFAULT_SEP = "&;",
    CLASS_MATCH = new RegExp("\\s([a-z|A-Z]+)");

  var objectClassName = function (object) {
    return CLASS_MATCH.exec(Object.prototype.toString.call(object))[1];
  };

  var unescape = function (s) {
    if (!s) {
      return s;
    }
    return decodeURIComponent(s.replace(/\+/g, "%20"));
  };

  var parseNestedQuery = function (queryString, d) {
    var params = {},
      matcher = new RegExp("[" + (d ? d : DEFAULT_SEP) + "] *"), //default regex /[&;] */
      kvPairs = (queryString || "").split(matcher),
      kvPair,
      k,
      v;
    for (var i = 0, length = kvPairs.length; i < length; i++) {
      kvPair = kvPairs[i].split("=", 2);
      k = unescape(kvPair[0]);
      v = unescape(kvPair[1]);
      normalize_params(params, k, v);
    }

    return params;
  };

  var matcherOne = new RegExp("^[\\[\\]]*([^\\[\\]]+)\\]*(.*)"),
    matcherTwo = new RegExp("^\\[\\]\\[([^\\[\\]]+)\\]$"),
    matcherThree = new RegExp("^\\[\\](.+)$"),
    arrayMatcher = new RegExp("^\\[\\s*\\]$");
  var normalize_params = function (params, name, v) {
    var kv = matcherOne.exec(name),
      k = (kv && kv[1]) || "",
      after = (kv && kv[2]) || "",
      last;

    if (k.length == 0) {
      return;
    }

    if (after == "") {
      params[k] = v;
    } else if (arrayMatcher.test(after)) {
      params[k] || (params[k] = []);

      if (!(objectClassName(params[k]) === "Array")) {
        throw (
          "expected Array (got " +
          objectClassName(params[k]) +
          ") for param `" +
          k +
          "'"
        );
      }

      params[k].push(v);
    } else if (
      (child_key = matcherTwo.exec(after)) ||
      (child_key = matcherThree.exec(after))
    ) {
      child_key = child_key[1];
      params[k] || (params[k] = []);

      if (!(objectClassName(params[k]) === "Array")) {
        throw (
          "expected Array (got " +
          objectClassName(params[k]) +
          ") for param `" +
          k +
          "'"
        );
      }

      last = params[k].length - 1;
      if (
        objectClassName(params[k][last]) === "Object" &&
        !params[k][last][child_key]
      ) {
        normalize_params(params[k][last], child_key, v);
      } else {
        params[k].push(normalize_params({}, child_key, v));
      }
    } else {
      params[k] || (params[k] = {});
      if (!(objectClassName(params[k]) === "Object")) {
        throw (
          "expected Hash (got " +
          objectClassName(params[k]) +
          ") for param `" +
          k +
          "'"
        );
      }

      params[k] = normalize_params(params[k], after, v);
    }
    return params;
  };

  return parseNestedQuery;
})();
$(document).ready(function() {
  var hasArticleAthletePortraitComponent = $(".component.article-athlete-portrait").length > 0;
  var athleteId = $('#data-athlete-id').text();
  var seasonUrl = $('#data-season-url').text();
  var seasonDesc = $('#data-season-desc').text();
  var sectorId = $('#data-sector-id').text();

  if ( hasArticleAthletePortraitComponent && athleteId.length > 0 ){
    if ($('#athlete-chart-rankings').length > 0) {
      $.getJSON('/charts.json?entity=athlete&type=rankings&athlete_id=' + athleteId + '&season=' + seasonUrl + '&sector_id=' + sectorId, function(data) {
        if (data.length > 0) {
          var chart = $('#athlete-chart-rankings .component.highchart');
          var options = chart.data('options');
          options.data = data;
          options.subtitle = 'Saison ' + seasonDesc;
          chart.data('options', options);
          chart.trigger('initChart');
        }
        else {
          $('#athlete-chart-rankings').hide();
        }
      });
    }

    if ($('#athlete-chart-successes').length > 0) {
      $.getJSON('/charts.json?entity=athlete&type=successes&athlete_id=' + athleteId + '&season=' + seasonUrl + '&sector_id=' + sectorId, function(data) {
        var numRanks = data['meta']['num_ranks'];

        if (numRanks > 0) {
          new Skizeit.Charting.SuccessesChart({
            renderTo: 'athlete-chart-successes',
            //categories: data['categories'],
            data: data['data'],
            subtitle: 'Saison ' + data['meta']['season_from'] + ' - ' + data['meta']['season_to']
          });
        }
        else {
          $('#athlete-chart-successes').hide();
        }
      });
    }

    // Points help tooltip
    $('.points .help > .glyphicon-question-sign').popover({
      trigger: 'hover',
      placement: 'top',
      html: 'true',
      container: 'body',
      content: function() { return $(this).siblings('.tooltip-contents').html(); }
    });

    // Points calculated tooltip
    $('.athlete-points .points-calculated .val').popover({
      trigger: 'hover',
      placement: 'right',
      html: 'true',
      sanitize: false,
      container: 'body',
      title: "Die 2 besten, bestätigten Ergebnisse",
      content: function() {
        var disciplineId = $(this).data('discipline-id');
        var seasonOfCurrentList = $(this).data('season-of-current-list');

        if (seasonOfCurrentList) {
          return "<div style='padding: 10px'>Wechseln Sie zu Saison " + seasonOfCurrentList + " um die Rennen anzuzeigen,<br />auf denen die Berechnung des Skizeit-Ranking basiert.</div>";
        } else {
          var rowsHtml = '';
          $('table.athlete_races_grid_view tbody tr.is_top_2_race.discipline-' + disciplineId).each(function() {
            rowsHtml += $(this).clone().prop('outerHTML');
          });
          return '<div class="races_grid_view"><table class="table" style="width: auto;">' + rowsHtml + '</table></div>';
        }
      },
      template: '<div class="popover" role="tooltip"><div class="arrow"></div><h3 class="popover-title"></h3><div class="popover-content"></div></div>'
    });

    let fetchAthletePointsHistory = async function(data) {
      let params = {
        season_id: data.seasonId,
        athlete_id: data.athleteId,
        discipline_id: data.disciplineId
      };

      try {
        let serverComponent = new ServerComponent();
        return await serverComponent.fetchHTML("athlete-points-history", params);
      } catch (e) {
        return "Daten konnten nicht geladen werden.";
      }
    };

    // Points history tooltip
    $('.athlete-points .points .val').
      mouseover(function() {
        if (Object.keys(this.dataset).length <= 0) { return; }

        let popover = $(this);
        fetchAthletePointsHistory(this.dataset).then(function(html) {
          popover.popover(
            {
              trigger: 'manual',
              placement: 'auto',
              html: 'true',
              sanitize: false,
              container: 'body',
              title: "Punkteverlauf", // TODO: Add discipline, i.e. "Punkteverlauf Slalom"
              content: html
            }
          ).popover("show");
        });
      }).
      mouseout(function() {
        $(this).popover("hide");
      });
  }
});
function extractCategoriesFromSeries(allSeries) {
  // convert from
  // [
  //   {
  //     data: [
  //       { name, custom: { timestamp } },
  //       ...
  //     ]
  //   },
  //   ...
  // ]
  //
  // to a list of unique name's, sorted by corresponding timestamp
  //
  // this list holds the categories of all the data points of all the points of
  // all the series

  let namesMap = allSeries.reduce(function(obj, series) {
    series.data.forEach(({ name, custom: { timestamp } }) => {
      obj[timestamp] = name;
    });
    return obj;
  }, {});

  let categories = Object.keys(namesMap).sort().map(key => namesMap[key]);
  return categories;
}
class AthletePointsChart extends HTMLElement {
  constructor() {
    super();

    this.chart = Highcharts.chart(this, this.options);
  }

  updateChart() {
    let series = this.getSeries();

    while (this.chart.series.length) {
      this.chart.series[0].remove(false);
    }

    let categories = extractCategoriesFromSeries(series);
    this.chart.xAxis[0].update({ categories }, false);

    for (const dataSeries of series) {
      this.chart.addSeries(dataSeries, false);
    }

    this.chart.redraw(false);

    for (const chartSeries of this.chart.series) {
      let lastPoint = chartSeries.points[chartSeries.points.length - 1];

      lastPoint?.update({
        dataLabels: {
          enabled: true,
          formatter() {
            return series[chartSeries.index].endLabel;
          },
        },
      });
    }
  }

  get options() {
    return {
      title: {
        text: this.title,
      },

      credits: { enabled: false },

      lang: {
        noData: "Disziplin / Punkteart auswählen",
      },

      plotOptions: {
        series: {
          animation: false,
        },

        chart: {
          type: "line",
        },
      },

      xAxis: {
        type: "category",
        crosshair: true,
        opposite: true,
        labels: {
          formatter() {
            // the value is the category of the datapoint, so dd.mm.yy
            // we only want to show dd.mm. so we only get the first 6 characters
            return this.value.slice(0, 6);
          }
        }
      },

      yAxis: {
        allowDecimals: this.allowDecimals,
        reversed: true,
        title: null,
      },

      series: [],
    };
  }

  getSeries() {
    let data = this.requestData({
      athleteIds: this.athleteIds,
      disciplineIds: this.disciplineIds,
      seasonIds: this.seasonIds,
    });

    // get a configuration for each series which should be shown
    let seriesConfigs = [];
    for (let athleteId of this.athleteIds) {
      for (let disciplineId of this.disciplineIds) {
        for (let dataField of this.dataFields) {
          seriesConfigs.push({
            athleteId,
            disciplineId,
            dataField,
          });
        }
      }
    }

    let series = seriesConfigs.map((seriesConfig) => {
      let discipline = this.disciplineMapping[seriesConfig.disciplineId];
      let dataPoint = this.pointMapping[seriesConfig.dataField];

      let endLabel = `${dataPoint.label}/${discipline.label}`;

      // TODO calculate better label depending on parameters (single/multiple
      // athletes; single/multiple disciplines; single/multiple dataFields)
      let athlete = this.athletes.find(athlete => athlete.id === seriesConfig.athleteId);
      let name = athlete.name;
      if (this.disciplineIds.length > 1) {
        name = `${athlete.name} (${endLabel})`;
      } else if (athlete.is_list_best) {
        name = `${athlete.name} (LB)`;
      } else if (athlete.is_year_best) {
        name = `${athlete.name} (JB)`;
      }

      let seriesData = {
        name,
        endLabel,

        type: "spline",

        dashStyle: dataPoint.dashStyle,

        color: discipline.color,

        data: data
          .filter((row) => {
            return (
              row.athlete_id == seriesConfig.athleteId &&
              row.discipline_id == seriesConfig.disciplineId
            );
          })
          .sort((a, b) => {
            let aDate = new Date(a.dat_valid_from);
            let bDate = new Date(b.dat_valid_from);

            return aDate.getTime() - bDate.getTime();
          })
          .map(data => ({
            name: Highcharts.dateFormat('%d.%m.%y', new Date(data.dat_valid_from)),
            y: parseFloat(data[seriesConfig.dataField]),
            custom: {
              timestamp: new Date(data.dat_valid_from).getTime(),
            },
          })),
      };

      let symbol = "circle";
      switch (seriesConfig.athleteId) {
        case this.main_athlete_id:
          symbol = "square";
          break;
        case this.include_list_best:
          symbol = "triangle-down";
          break;
        case this.include_year_best:
          symbol = "diamond";
          break;
      }

      seriesData.marker = {
        symbol,
      };

      return seriesData;
    });

    return series;
  }

  update(obj) {
    this.athleteIds = this.athletes.map((s) => s.id);
    this.disciplineIds = obj.disciplines.map((s) => parseInt(s));

    this.main_athlete_id = parseInt(obj.main_athlete_id);

    if (obj.include_list_best) {
      this.include_list_best = this.athletes.find(athlete => athlete.is_list_best)?.id;
    }
    if (obj.include_year_best) {
      this.include_year_best = this.athletes.find(athlete => athlete.is_year_best)?.id;
    }

    this.dataFields = obj.points_type.map((pT) =>
      `${this.type}_${pT}`.replace("points_points", "points")
    );

    this.updateChart();
  }

  get seasonIds() {
    return [];
  }

  get type() {
    return this.getAttribute("type");
  }

  get title() {
    return this.getAttribute("title");
  }

  get athleteChart() {
    return this.closest("athlete-chart");
  }

  get allowDecimals() {
    if (this.type === "rank") {
      return false;
    }

    return true;
  }

  get athletes() {
    return this.athleteChart.athletes();
  }

  get pointMapping() {
    return this.athleteChart.pointMapping();
  }

  get disciplineMapping() {
    return this.athleteChart.disciplineMapping();
  }

  requestData(params) {
    let data = this.athleteChart.dataPoints();

    let filtered = data.filter((row) => {
      return (
        params.athleteIds.includes(row.athlete_id) &&
        params.disciplineIds.includes(row.discipline_id)
      );
    });

    return filtered;
  }
}

customElements.define("athlete-points-chart", AthletePointsChart);
class AthleteChart extends HTMLElement {
  constructor() {
    super();

    this.form = this.querySelector("form");
    this.addEventListener("change", () => this.updateCharts());

    this.setupData();

    this.updateCharts();
  }

  setupData() {
    let dataPoints = this.querySelector("[data-points]").textContent;
    this._dataPoints = JSON.parse(dataPoints);

    let athletes = this.querySelector("[data-athletes]").textContent;
    this._athletes = JSON.parse(athletes);

    let pointMapping = this.querySelector("[data-point-mapping]").textContent;
    this._pointMapping = JSON.parse(pointMapping);

    let disciplineMapping = this.querySelector("[data-discipline-mapping]").textContent;
    this._disciplineMapping = JSON.parse(disciplineMapping);

    this._loadedAthletes = [];
    this._loadedDataPoints = [];
  }

  athletes() {
    return [...this._athletes, ...this._loadedAthletes];
  }

  dataPoints() {
    return [...this._dataPoints, ...this._loadedDataPoints];
  }

  pointMapping() {
    return this._pointMapping;
  }

  get athleteIds() {
    let selectEntityRelationsDropdown = this.querySelector(".athlete-selection entity-relations");
    if (selectEntityRelationsDropdown) {
      let entities = selectEntityRelationsDropdown.dataEntityRelations?.added ?? [];
      let athleteIds = entities.map(entity => parseInt(entity.relationEntityId));
      return athleteIds;
    }

    return [];
  }

  disciplineMapping() {
    return this._disciplineMapping;
  }

  async updateCharts() {
    let data = new FormData(this.form);
    let formJSON = Object.fromEntries(data.entries());

    ["points_type", "disciplines"].forEach((key) => {
      formJSON[key] = data.getAll(key);
    });

    formJSON['athlete_ids'] = this.athleteIds;

    let showComparison;

    if (formJSON.points_type.length === 1 && formJSON.disciplines.length === 1) {
      showComparison = true;
    } else {
      showComparison = false;
      delete formJSON.include_year_best;
      delete formJSON.include_list_best;
    }

    let classes = this.querySelector(".comparison").classList;
    if (showComparison) {
      classes.remove("hidden");
    } else {
      classes.add("hidden");
    }

    if (showComparison) {
      await this.fetchAdditionalData(formJSON);
    } else {
      this._loadedDataPoints = [];
      this._loadedAthletes = [];
    }

    let charts = this.querySelectorAll("athlete-points-chart");
    charts.forEach((chart) => chart.update(formJSON));
  }

  async fetchAdditionalData(params) {
    this._loadedDataPoints = [];
    this._loadedAthletes = [];

    if (params.include_list_best || params.include_year_best || params.athlete_ids.length) {
      let queryParams = new URLSearchParams();
      queryParams.append("athlete_id", params.main_athlete_id);
      queryParams.append("season_id", params.season_id);
      queryParams.append("discipline_id", params.disciplines[0]);
      queryParams.append("points_type", params.points_type[0]);
      queryParams.append("include_list_best", params.include_list_best ?? false);
      queryParams.append("include_year_best", params.include_year_best ?? false);
      queryParams.append("is_intra_region_comparison", params.is_intra_region_comparison ?? false);

      if (params.athlete_ids.length) {
        params.athlete_ids.forEach(athleteId => {
          queryParams.append("athlete_ids[]", athleteId);
        });
      }

      // TODO abortable, so previous request for a selection is not considered?
      let response = await fetch(`/api/entities/points?${queryParams}`);

      if (response.ok) {
        let data = await response.json();
        this._loadedDataPoints = data.points;
        this._loadedAthletes = data.athletes;
      }
    }
  }
}

customElements.define("athlete-chart", AthleteChart);
