class CheckboxColumnControl extends HTMLElement {
  connectedCallback() {
    this.selectAllCheckbox = this.querySelector(this._selector());
    this.colIndex = Array.from(this.closest('th').parentElement.children).indexOf(this.closest('th'));
    this.selectAllCheckbox.addEventListener(this._eventType(), this.handleSelectAllChange.bind(this));
    this.table = this.closest('table');

    this.table.addEventListener('change', this.handleRowCheckboxChange.bind(this));
    this.observer = this.attachObserver();
    this.updateSelectAllCheckboxState();
  }

  disconnectedCallback() {
    this.selectAllCheckbox.removeEventListener('change', this.handleSelectAllChange.bind(this));
    this.table.removeEventListener('change', this.handleRowCheckboxChange.bind(this));
    this.observer.disconnect();
  }

  rowCheckboxes(includeDisabled = false) {
    let selector = `td:nth-of-type(${this.colIndex + 1}) input[type="checkbox"]`;

    if (includeDisabled === false) {
      selector += ":not([disabled])"
    }

    return Array.from(
      this.table.querySelectorAll(selector)
    );
  }

  handleRowCheckboxChange(e) {
    if (this.rowCheckboxes().includes(e.target)) {
      this.updateSelectAllCheckboxState();
    }

    const numChecked = this.rowCheckboxes(true).filter(checkbox => checkbox.checked).length;
    let valChangedEvent = new CustomEvent("valChanged", {
      detail: { name: "numChecked", val: numChecked }
    });
    this.dispatchEvent(valChangedEvent);
  }

  attachObserver() {
    const observer = new MutationObserver((mutations) => {
      mutations.forEach((mutation) => {
        if (mutation.type === 'childList') {
          this.updateSelectAllCheckboxState();
        }
      });
    });

    observer.observe(this.table.querySelector('tbody'), { childList: true, subtree: false });

    return observer;
  }
}

class CheckAllCheckbox extends CheckboxColumnControl {
  handleSelectAllChange() {
    const isChecked = this.selectAllCheckbox.checked;
    this.rowCheckboxes().forEach(checkbox => {
      checkbox.checked = isChecked;

      // Required so form-sync is gonna be involved, hence making the (un)checking
      // state applied to the "right" component as well
      checkbox.dispatchEvent(new Event("change", { bubbles: true }));
    });
  }

  updateSelectAllCheckboxState() {
    const allRowCheckboxesChecked = this.rowCheckboxes(true).every(checkbox => checkbox.checked);
    this.selectAllCheckbox.checked = allRowCheckboxesChecked;
    this.selectAllCheckbox.disabled = this.rowCheckboxes().length === 0;
  }

  _selector() { return "input[type='checkbox']"; }
  _eventType() { return "change"; }
}

class RemoveAllButton extends CheckboxColumnControl {
  handleSelectAllChange(e) {
    e.preventDefault();
    this.rowCheckboxes().forEach(checkbox => {
      checkbox.checked = false;

      // Required so form-sync is gonna be involved, hence making the unchecking
      // state applied to the "left" component as well
      checkbox.dispatchEvent(new Event("change", { bubbles: true }));
    });
    this.selectAllCheckbox.disabled = true;
  }

  updateSelectAllCheckboxState() {
    const allRowCheckboxesUnchecked = this.rowCheckboxes().every(checkbox => !checkbox.checked);
    this.selectAllCheckbox.disabled = allRowCheckboxesUnchecked;
    this.selectAllCheckbox.dispatchEvent(new Event("change", { bubbles: true }));
  }

  _selector() { return "button"; }
  _eventType() { return "click"; }
}

