Skizeit.Components.DeferredComponent = (function() {
  var Constr = function() {
    this.toggle = toggle;
  };

  var toggle = function(component) {
    var isLoaded = component.data('is-loaded') == true;
    var isVisible = component.data('is-visible') == true;

    if (isVisible) {
      component.data('is-visible', false);
      component.hide();
    } else {
      component.data('is-visible', true);
      component.show();
      if (!isLoaded) {
        load(component);
        component.data('is-loaded', true);
      }
    }
  };

  var load = function(component) {
    component.find('.loading-indicator').show();
    var componentName = component.data('name');
    var params = component.data('params');
    var componentUrl = '/components/' + componentName + '?' + params;
    $.get(componentUrl, function(html) {
      component.html(html);
    });
  };

  return Constr;
}());
