class DropDown extends HTMLElement {
  constructor() {
    super();

    document.addEventListener("click", this.handleClick.bind(this));
  }

  handleClick(e) {
    // If there is a specific trigger, i.e. an element with class "trigger", use
    // this one, otherwise use the whole ".drop-down-trigger" area as trigger.
    const specificTrigger = this.querySelector(".drop-down-trigger .trigger");
    const trigger = specificTrigger ?? this.querySelector(".drop-down-trigger");
    const content = this.querySelector(".drop-down-content")
    const isOpen = this.classList.contains("open");


    if (!this.contains(e.target)) {
      // event didn't happen in this web component
      // - if it's not open, we ignore this event therefore
      // - if it's open, it means a click outside, which we want to handle

      if (!isOpen) {
        return;
      }
    }

    // click on trigger opens content
    if ((trigger == e.target || trigger.contains(e.target)) && !this.classList.contains("open")) {
      this.classList.add("open");
      return;
    }

    // ignore clicks within content
    if (content == e.target || content.contains(e.target)) {
      return;
    }

    // click outside
    this.close();

    this.dispatchEvent(new CustomEvent("drop-down-closed"));
  }

  close() {
    this.classList.remove("open");
  }
}

customElements.define("drop-down", DropDown);
class EntityRelations extends HTMLElement {
  connectedCallback() {
    if (this.classList.contains("is-public")) return;

    this.addEventListener("click", this.handleClick.bind(this));
    this.formState.addEventListener("form-state-changed", this.handleFormStateChanged.bind(this));

    let defaultEntityRelations = this.querySelectorAll(".entity-relation[data-is-default='true']");
    if (defaultEntityRelations.length > 0) {
      defaultEntityRelations.forEach((entityRelation) => {
        let checkbox = this._getCheckboxForEntityRelation(entityRelation);
        checkbox.dispatchEvent(this._createChangeEvent());
      });

      this.closest("select-entity-relations-dropdown").triggerChange();
    }
  }

  handleClick(e) {
    let clickedOnClose = e.target.closest(".remove");
    if (!clickedOnClose) {
      return;
    }

    // Forward click on "x" icon to make change on correlating checkbox
    let checkbox = this._getCheckboxForEntityRelation(e.target.closest(".entity-relation"));
    checkbox.checked = false;
    checkbox.dispatchEvent(this._createChangeEvent());
  }

  handleFormStateChanged(e) {
    let data = e.detail;
    let entityTypes = this.dataset.entityTypes.split(",");

    // TODO: Maybe we can change this to already add in "addEventListener", which collection types
    // we want to listen to
    if (data.collectionType == "entity_relations") {
      let entityRelations = this.querySelectorAll(`.entity-relation[data-id='${data.id}']`);

      if (entityRelations.length === 0) {
        if (entityTypes.includes(data.entity.relation_entity_type)) {
          if (data.entity.is_deleted === "0") {
            this.addNew({ id: data.id, ...data.entity });
          }
        }
      } else {
        let entityRelationElement = entityRelations[0]; // Should be always only one here

        // If we could use `:has` selector already (Firefox is missing support), we would
        // not need the code below
        if (entityRelationElement.querySelectorAll("input[type='checkbox']")[0].checked) {
          entityRelationElement.classList.remove("is-deleted");
        } else {
          entityRelationElement.classList.add("is-deleted");
        }
      }
    }
  }

  addNew(entity) {
    // TODO: Extract `inject` into global helper method and rename
    // Taken from https://stackoverflow.com/a/55594573
    let inject = (str, obj) => str.replace(/\${(.*?)}/g, (x,g)=> obj[g]);

    let args = {
      id: entity.id,
      relation_entity_type: entity.relation_entity_type,
      relation_entity_id: entity.relation_entity_id,
      relation_entity_description: entity.__description__
    };

    let template = this.getElementsByTagName("template")[0].innerHTML;
    let newHTML = inject(template, args);

    let emptyElement = this.querySelectorAll(".entity-relation-empty")[0];
    emptyElement.insertAdjacentHTML("beforebegin", newHTML);
  }

  get dataEntityRelations() {
    return this.constructor.getDataEntityRelations(this.formData);
  }

  static getDataEntityRelations(formData) {
    return (new EntityRelations.DataTransformer(formData)).data;
  }

  get formState() {
    // TODO: Allow to specify used form-state via `data-` attribute
    return document.querySelector("form-state[data-name='default']");
  }

  get formData() {
    return this.formState.changes;
  }

  _createChangeEvent() {
    return new Event("change", { bubbles: true });
  }

  _getCheckboxForEntityRelation(entityRelation) {
    return entityRelation.querySelectorAll("input[type='checkbox']")[0];
  }
}

EntityRelations.DataTransformer = class {
  constructor(formData) {
    this.formData = formData;
  }

  get data() { // => dataEntityRelations
    return {
      added: this._added.map(item => this._itemToEntityRelation(item)),
      removed: this._removed.map(item => this._itemToEntityRelation(item))
    };
  }

  // Clearer name would be `active` or similar
  get _added() {
    return this._entityRelationsForState("0");
  }

  // Clearer name would be `inactive` or similar
  get _removed() {
    return this._entityRelationsForState("1");
  }

  _entityRelationsForState(isDeleted) {
    let entityRelations = this.formData.entity_relations || [];
    return entityRelations.filter((entityRelation) => { return entityRelation.is_deleted === isDeleted });
  }

  _itemToEntityRelation(data) {
    let isNew = !(new RegExp(/^\d+$/).test(data.id));

    // TODO: Replace with generic `snakeCaseToCamelcase` method
    return {
      // we have to ensure manually / explicitly here that no value for `id` is passed, as
      // ember (data) does not work well with `id` for new records (i.e. unpersisted ids)
      // that is, if a record has been added already once with that id, is then deleted locally
      // and would then be tried to be added again, an error occurs, as the store stays that
      // there is already a record with that id
      id: isNew ? null : data.id,
      entityType: data.entity_type, entityId: data.entity_id,
      relationEntityType: data.relation_entity_type, relationEntityId: data.relation_entity_id,
      relationType: data.relation_type
    };
  }
}

customElements.define("entity-relations", EntityRelations);
