class FileUpload extends HTMLElement {
  fileUploadMap = new Map();

  connectedCallback() {
    let input = this.querySelector("input");

    if (input) {
      this.setupFileUpload(input);
      return;
    }

    // Using this component in Ember.js: the child elements aren't available in this callback yet,
    // so we register a mutation observer to get notified when a <input type="file" /> is available
    //
    // TODO: once Ember.js has been ditched, the code below can be removed as the input element should always
    // be available above
    let observer = new MutationObserver((mutations) => {
      let input = this.querySelector("input");
      if (input) {
        observer.disconnect();
        this.setupFileUpload(input);
      }
    })

    observer.observe(this, { childList: true });
  }

  disconnectedCallback() {
    try {
      $('input', this).fileupload('destroy');
    } catch {
      // ignore
    }
  }

  setupFileUpload(input) {
    let dropZone = this.closest('.drop-zone');
    $(input).fileupload({
      dropZone: dropZone || input,

      // limit to 2 concurrent uploads
      limitConcurrentUploads: 2,

      // take the image orientation from the EXIF data, if available
      imageOrientation: true,
      disableImageMetaDataSave: true,

      // Enable image resizing, except for Android and Opera, which actually
      // support image resizing, but fail to send Blob objects via XHR
      // requests:
      disableImageResize: isAndroid() || isOpera(),

      imageMaxWidth: 2000,
      imageMaxHeight: 2000,

      progressInterval: 20,

      // specify max file size for loadImage processQueue plugin, so images up until
      // 100mb are loaded and processed
      loadImageMaxFileSize: 100_000_000,

      change: (evt, data) => {
        return this._prepareFiles(evt, data)
      },

      drop: (evt, data) => {
        return this._prepareFiles(evt, data);
      },

      add: (evt, data) => {
        this._uploadFile(data);
      },

      progress: (evt, data) => {
        let [file] = data.files;

        let uuid = this.fileUploadMap.get(file.name);
        let progress = parseInt(data.loaded / data.total * 100, 10);

        this.dispatchEvent(new CustomEvent('file-progress', {
          detail: { uuid, progress },
          bubbles: true,
          composed: true
        }));
      }
    });
  }

  _prepareFiles(evt, data) {
    let files = data.files.map(file => {
      let uuid = randomUUID()

      this.fileUploadMap.set(file.name, uuid);

      return {
        uuid,
        fileName: file.name,
        fileType: file.type
      };
    });

    let event = new CustomEvent('files-selected', {
      detail: { files },
      cancelable: true,
      bubbles: true,
    });

    this.dispatchEvent(event);

    if (event.defaultPrevented) {
      return false;
    }

    // delete ignored files from the uploadMap, so we don't upload those files
    event.detail.files
      .filter((f) => f.ignore)
      .forEach((f) => {
        this.fileUploadMap.delete(f.fileName);
      });
  }

  async _uploadFile(data) {
    let [file] = data.files;

    // check if the file has been deleted from the uploadMap, and if so, we don't upload the file
    let uuid = this.fileUploadMap.get(file.name);
    if (!uuid) {
      return;
    }

    let fileName = file.name.replace(/[^a-z0-9\.\-]/gi, '_');

    let acl = this.getAttribute("acl");
    let credentials = await fetch(`/api/credentials?content_type=true&acl=${acl}&key=${fileName}`).then(res => res.json());

    let key = `${credentials.upload_directory}/${fileName}`;
    let uploadedFileUrl = credentials.url + '/' + key;
    let signedUrl = credentials.get_url;

    data.formData = {
      key: key,
      acl: credentials.acl,
      policy: credentials.policy,
      signature: credentials.signature,
      AWSAccessKeyId: credentials.aws_access_key_id,
      'Content-Type': file.type
    };

    // TODO save returned jqXHR so we can cancel an upload
    // https://github.com/blueimp/jQuery-File-Upload/wiki/API#how-to-cancel-an-upload
    data.url = credentials.url;

    let input = this.querySelector("input");

    // TODO: handle error
    await $(input).fileupload('process', data);

    let jqXHR = data.submit();

    try {
      await jqXHR;

      this.dispatchEvent(new CustomEvent('file-uploaded', {
        detail: {
          uuid,
          url: uploadedFileUrl,
          signedUrl: signedUrl
        },
        bubbles: true,
        composed: true
      }));
    } catch (e) {
      this.dispatchEvent(new CustomEvent('file-upload-failed', {
        detail: {
          uuid,
          errorMessage: e.statusText
        },
        bubbles: true,
        composed: true
      }));
    }
  }
}

function s4() {
  return Math.floor((1 + Math.random()) * 0x10000)
    .toString(16)
    .substring(1);
}

function randomUUID() {
  return s4() + s4() + '-' + s4() + '-' + s4() + '-' +
    s4() + '-' + s4() + s4() + s4();
}

function isAndroid() {
  return /Android(?!.*Chrome)/.test(window.navigator && navigator.userAgent);
}

function isOpera() {
  return /Opera/.test(window.navigator && navigator.userAgent);
}

