//
// Connect a `form` to a `form-state`:
// E.g.:
// <form data-form-state='default'>
// <form data-form-state='default,registrations'>
//
class FormState extends HTMLElement {
  constructor() {
    super();
    this.state = {};
  }

  connectedCallback() {
    this._onChangeListener = this._onChange.bind(this);
    this._componentRenderedListener = this._componentRendered.bind(this);

    document.addEventListener("change", this._onChangeListener);
    document.addEventListener("skizeit:component-rendered", this._componentRenderedListener);
  }

  disconnectedCallback() {
    document.removeEventListener("change", this._onChangeListener);
    document.removeEventListener("skizeit:component-rendered", this._componentRenderedListener);
  }

  get formData() {
    let forms = this._connectedForms;

    // TODO: support multiple `form`s connected to same `form-state`
    let form = forms[0];

    return this._toObject(new FormData(form));
  }

  get changes() {
    return this._toObjectArray(this.state);
  }

  _onChange(e) {
    if (!this._hasConnectedForm) return;

    let target = e.target;
    let form = target.form;

    if (!target.name) {
      return;
    }

    let obj = Skizeit.Utils.objectify(target.name)
    let collectionType = Object.keys(obj)[0];
    let id = Object.keys(obj[collectionType] || {})[0];
    // let attrName = Object.keys(obj[collectionType][id])[0];

    if (!id) {
      // Do we want to support form elements with different (arbitrary) name
      // structure as well (i.e. not `:collection_type[:id][:attr_name]`)?

      console.log(`Ignoring field: ${target.name}`);
      return;
    }

    let isNew = !(new RegExp(/^\d+$/).test(id));
    if (isNew) {
      let elems = document.querySelectorAll(`[name^='${collectionType}[${id}]']`);
      for (let i = 0; i < elems.length; i++) {
        this._updateState(elems[i]);
      }
    }

    // Ensure that state of source of the change event is always applied last
    this._updateState(target);

    // This reconcile is handling the "binding" between form elements
    // with same name.
    this._reconcileState({ [target.name]: this.state[target.name] });

    this.dispatchEvent(
      new CustomEvent("form-state-changed", {
        detail: {
          collectionType: collectionType,
          id: id,
          entity: this.formData[collectionType][id]
          // changes: this.changes[collectionType][id]
        }
      })
    );

    // This reconcile is handling the "binding" between form elements
    // with the same name for elements that might get added as a reaction to event
    // "form-state-changed", e.g. when a new element is added from a `template` item.
    this._reconcileState(this.state);
  }

  _componentRendered(e) {
    if (!this._hasConnectedForm) return;

    // Reconciles states of form elements that have been newly received from
    // server.
    this._reconcileState(this.state);
  }

  _updateState(elem) {
    if (elem.type == "checkbox") {
      if (elem.checked) {
        this.state[elem.name] = elem.value;
      } else {
        let hiddenTarget = document.querySelector(`input[type='hidden'][name='${elem.name}']`);
        this.state[elem.name] = hiddenTarget.value;
      }
    } else {
      this.state[elem.name] = elem.value;
    }
  }

  _reconcileState(state) {
    for (const fieldName in state) {
      let fields = document.getElementsByName(fieldName);
      let isCheckbox = Array.from(fields).some((field) => { return field.type === "checkbox"; });
      let isRadio = Array.from(fields).some((field) => { return field.type === "radio"; });

      for (let i = 0; i < fields.length; i++) {
        const field = fields[i];

        if (this._isConnectedForm(field.form)) {
          if (isCheckbox) {
            if (field.type === "checkbox") {
              let newVal = field.value == state[fieldName];

              if (field.checked !== newVal) {
                field.checked = newVal;
                // dispatchEvent for all field types (?)
                field.dispatchEvent(new Event("change", { bubbles: true }));
              }
            }
            // don't do anything for hidden field that is related to this checkbox
          } else if (isRadio) {
            // Reconciling radion buttons is not possible (at the moment).
            // This would not work in the normal way, as a group of radion
            // buttons all share the same name.
            // Maybe the matching has to be done here by `name + value` as this
            // is what identifies an individual radion button element.
          } else {
            field.value = state[fieldName];
          }
        }
      }
    }
  }

  get _hasConnectedForm() {
    return this._connectedForms.length > 0;
  }

  _isConnectedForm(form) {
    return this._connectedForms.includes(form)
  }

  get _connectedForms() {
    let name = this.dataset.name;
    let connectedForms = document.querySelectorAll(`form[data-form-state*='${name}']`);
    return Array.from(connectedForms).filter((form) => {
      let formStates = form.dataset.formState.split(",");
      return formStates.includes(name);
    });
  }

  // TODO: Extract out into generic utility function
  //
  // Converts formData to object in the form of:
  // {
  //   "collection_type": {
  //    "id-1": { ... },
  //    "id-2": { ... },
  //   }
  // }
  _toObject(formData) {
    return Skizeit.Utils.objectify(
      new URLSearchParams(formData).toString()
    );
  }

  // TODO: Extract out into generic utility function
  //
  // Converts formData to object in the form of:
  // {
  //   "collection_type": [
  //    { "id": "id-1", ... },
  //    { "id": "id-2", ... }
  //   ]
  // }
  _toObjectArray(formData) {
    let obj = this._toObject(formData);
    let result = {};

    Object.keys(obj).forEach((collectionName) => {
      let collectionByIds = obj[collectionName];

      let collection = Object.keys(collectionByIds).map((id) => {
        return Object.assign({ id: id }, collectionByIds[id]);
      });

      result[collectionName] = collection;
    });

    return result;
  }
}

customElements.define("form-state", FormState);
Skizeit.Components.Highchart = (function() {
  var func = function(e) {
    $(".component.highchart").each(function() {
      $(this).on('initChart', function() {
        var options = $(this).data('options');

        if (options.chartTypeClass) {
          $(this).closest('.statistic-chart').find('.show-more a').hide();
          var chart = Skizeit.Components.Highchart[options.chartTypeClass];
          if (chart) {
            options = chart.buildOptions(options);
          }
        } else if (options.xAxis) {
          var numEntries = options.xAxis.categories.length;
          var numEntriesShown = numEntries;

          if (options.xAxis.max) {
            if (numEntries <= options.xAxis.max) {
              options.xAxis.max = undefined;
            } else {
              numEntriesShown = options.xAxis.max;
            }
          }

          var height = numEntriesShown * 20 + 130;

          options.chart.height = height;

          if (numEntriesShown === numEntries) {
            $(this).closest('.statistic-chart').find('.show-more a').hide();
            $(this).closest('.is-expandable').removeClass('is-expandable');
          }
        }

        options.chart.renderTo = this;

        new Highcharts.Chart(options);
      });
      $(this).trigger('initChart');
    });
  };

  var init = function() {
    $(document).ready(func);
    $(document).on('becameVisible', func);
  };

  return { init: init };
}());

