Skizeit.Components.Highchart.AthleteRankingsChart = {
  buildOptions: function(options){
    var newOptions = {
      chart: {
         type: 'spline',
         alignTicks: true
      },
      credits: { enabled: false },
      title: {},
      subtitle: {},
      tooltip: {
        formatter: function() {
            var description = this.points[0].series.chart.options.customData[this.x].description;
            var s = '<b>'+ description +'</b>';

            $.each(this.points, function(i, point) {
                var y = point.y;
                if (point.series.name != 'Zielstatus' && y >= 25){
                  y = point.series.options.dataReal[point.x];
                }

                if (point.series.name == 'Zielstatus'){
                  y = point.series.options.dataReal[point.x];
                }

                s += '<br/>'+ point.series.name +': '+
                    y;
            });

            return s;
        },
        shared: true,
        crosshairs: true
      },
      xAxis: {
        labels: {
            rotation: 90,
            formatter: function() {
              var datRace = this.chart.options.customData[this.value].datRace;
              return datRace;
            }
        }
      },
      yAxis: [{
         title: {
            text: 'Rang'
         },
          reversed: true,
          min: 1,
          max: 35,
          tickPositions: [1, 5, 10, 15, 20, 25, 30, 35],
          labels: {
              formatter: function() {
                  if ( this.value == 25 ) return '25+';
                  if ( this.value == 30) return 'Status';
                  if ( this.value > 25) return '';
                  return this.value;
              }
          }
      }]
    };

    newOptions.chart.renderTo = options.renderTo;
    newOptions.subtitle.text = options.subtitle;
    newOptions.title.text = '';
    newOptions.series = [
      this.seriesPosClass(options.data),
      this.seriesPosAll(options.data),
      this.seriesStatus(options.data)
    ];
    newOptions.customData = this.customData(options.data);
    newOptions.xAxis.categories = this.categories(options.data);

    return newOptions;
  },

  seriesPosClass: function(data){
    var series = { name: 'Klassenrang', data: [], dataReal: [] };
    $.each(data, function( i, val ) {
      var pos = val.pos_class;
      if (pos != null) {
        var point = [i, pos > 25 ? 25 : pos];
        series['data'].push(point);
        series['dataReal'][i] = pos;
      }
    });
    return series;
  },

  seriesPosAll: function(data){
    var series = { name: 'Gesamtrang', data: [], dataReal: [] };
    $.each(data, function( i, val ) {
      var pos = val.pos_all;
      if (pos != null) {
        var point = [i, pos > 25 ? 25 : pos];
        series['data'].push(point);
        series['dataReal'][i] = pos;
      }
    });
    return series;
  },

  seriesStatus: function(data){
    var series = { name: 'Zielstatus', data: [], dataReal: [] };
    $.each(data, function( i, val ) {
      var status = 30;
      if ( val.status != 'IZ' ) status = 35;
      var point = [i, status];
      series['data'].push(point);
      series['dataReal'].push(val.status);
    });
    return series;
  },

  customData: function(data){
    var customData = [];
    $.each(data, function( i, val ) {
      customData.push({
        datRace: val.dat_race,
        description: val.description
      });
    });
    return customData;
  },

  categories: function(data){
    return $.map(data, function( val, i ) {
      return i;
    });
  }
};
