class MessageRecipients extends HTMLElement {
  connectedCallback() {
    // TODO: `let form = this.closest("form");` once we have `form-state` nested
    let formState = document.querySelector("form-state[data-name='default']");
    formState.addEventListener("form-state-changed", this._handleFormStateChanged.bind(this));
    this._updateSelectedClubsState();
  }

  _updateSelectedClubsState() {
    let selectedClubs = this.querySelector(".selected-clubs");
    let recipientsTypeRadio = this.querySelector(".recipients-types input[type='radio']:checked");

    if (recipientsTypeRadio.value === "clubs_selected") {
      selectedClubs.classList.remove("disabled");
    } else {
      selectedClubs.classList.add("disabled");
    }
  }

  _handleFormStateChanged(e) {
    this._updateSelectedClubsState();

    let formState = e.target;

    let dataEntityRelations = EntityRelations.getDataEntityRelations(formState.changes);

    let articleId = this.dataset.articleId;
    let recipientsOptions = formState.formData.articles[articleId].recipients_options;

    let detail = {
      entityRelations: dataEntityRelations,
      recipientsOptions: recipientsOptions
    };

    this.dispatchEvent(new CustomEvent("recipients-changed", { detail: detail, bubbles: true }));
  }
}

