Skizeit.Components.PaginationMore = (function() {
  var Constr = function() {
    this.more = more;
  };

  var more = function(trigger) {
    trigger = $(trigger);
    var componentUrl = trigger.data('component-url');
    var paginationReverse = trigger.data('pagination-reverse');

    trigger.addClass('loading');
    $.get(componentUrl, function(html) {
      var componentName = trigger.data('component-name');
      var component = trigger.closest('[data-component="' + componentName + '"]');

      var itemsContainerName = trigger.data('component-items-container');
      var itemsContainerSelector = '[data-items-container="' + itemsContainerName + '"]';
      var existingItemsHtml = component.find(itemsContainerSelector).html();

      var newComponentHtml = $(html);
      var lastNewItemId = newComponentHtml.find(itemsContainerSelector).children().last().attr('id');

      if (paginationReverse) {
        newComponentHtml.find(itemsContainerSelector).append(existingItemsHtml);
      } else {
        newComponentHtml.find(itemsContainerSelector).prepend(existingItemsHtml);
      }

      component.html(newComponentHtml.html());
      $(document).trigger('becameVisible', [component]);

      if (paginationReverse) {
        $('html, body').scrollTop($('#' + lastNewItemId).offset().top);
      }
    });
  };

  return Constr;
}());
$(document).ready(function() {
  var $pswp = $('.pswp')[0];

  var getItems = function(container) {
    var items = [];
    container.find('a.pswp-picture').each(function() {
      var href   = $(this).attr('href'),
          width  = $(this).data('width');
          height = $(this).data('height');
          title  = $(this).data('title');

      var item = {
          src   : href,
          w     : width,
          h     : height,
          title : title
      }

      items.push(item);
    });
    return items;
  };

  $(document).on('click', 'a.pswp-picture', function(event) {
    event.preventDefault();

    var container = $(this).closest('.pswp-pictures-container');
    var index = container.find('a.pswp-picture').index($(this));

    var items = getItems(container);

    var options = {
      index: index,
      bgOpacity: 0.7,
      showHideOpacity: true,
      shareButtons: [
        { id: 'download', label: 'Herunterladen', url: '{{raw_image_url}}', download: true }
      ],
      closeElClasses: [],
      zoomEl: false,
      clickToCloseNonZoomable: false,
      getDoubleTapZoom: function(isMouseClick, item) {
        if(isMouseClick) {
          return item.initialZoomLevel;
        } else {
          // is double-tap
          // zoom to original if initial zoom is less than 0.7x,
          // otherwise to 1.5x, to make sure that double-tap gesture always zooms image
          return item.initialZoomLevel < 0.7 ? 1 : 1.5;
        }
      }
    };

    var isIntegrated = $('body').hasClass('integrated');

    var initPhotoSwipe = function() {
      var photoSwipe = new PhotoSwipe($pswp, PhotoSwipeUI_Default, items, options);
      photoSwipe.init();

      var tapCallback = function(e) {
        if (e.detail.pointerType === 'mouse') {
          var pswpItem = $(e.detail.target).closest('.pswp__item')[0];
          var releasePoint = e.detail.releasePoint;
          var centerX = pswpItem.clientWidth / 2;
          var mouseX = releasePoint.x;

          if (mouseX >= centerX) {
            photoSwipe.next();
          } else {
            photoSwipe.prev();
          }
        }
      };

      photoSwipe.framework.bind(photoSwipe.scrollWrap, 'pswpTap', tapCallback);

      photoSwipe.listen('destroy', function(e) {
        this.framework.unbind(this.scrollWrap, 'pswpTap', tapCallback);
      });
    }

    var parentIFrame = window.parentIFrame;

    if (isIntegrated && parentIFrame) {
      var trigger = $(this)[0];
      var clientRect = trigger.getBoundingClientRect();
      var pageInfo = parentIFrame.getPageInfo(
        function(pageInfo) {
          var paddingTop = 20;
          var scrollTop = pageInfo.scrollTop - pageInfo.offsetTop - paddingTop;
          var height = pageInfo.clientHeight;
          if (scrollTop < 0) {
            height = height + scrollTop;
            scrollTop = 0;
          }
          $('.pswp').css('position', 'fixed');
          $('.pswp').css('top', scrollTop + 'px');
          $('.pswp').css('height', height + 'px');

          initPhotoSwipe();

          parentIFrame.getPageInfo(false);
        }
      );
    } else {
      initPhotoSwipe();
    }
  });
});
