$(document).ready(function() {
  var lastSearchTerm = '';
  var inputSelector = '.component.search-field input';

  var executeSearch = function() {
    var trigger = $(this);
    var spinner = trigger.siblings('.spinner-wrapper').find('.spinkit-spinner');
    var paramName = trigger.data('param-name');
    var searchTerm = trigger.val();
    var componentUrl = trigger.data('component-url');
    var componentName = trigger.data('component-name');
    var component = trigger.closest('[data-component="' + componentName + '"]');

    if (!componentUrl) {
      var nativeComponent = component[0];
      componentUrl = nativeComponent.dataUrl();
    }

    componentUrl = URI(componentUrl).setSearch(paramName, searchTerm).toString();
    spinner.show();

    $.get(componentUrl, function(html) {
      var newHTML = $(html);
      var lastSearchTerm = trigger.val();
      var currentSearchTerm = newHTML.find(inputSelector).val();

      if (currentSearchTerm === lastSearchTerm) {
        component[0].innerHTML = newHTML[0].innerHTML;

        $(document).trigger('becameVisible', [component]);
        document.dispatchEvent(new CustomEvent("skizeit:component-rendered"));

        // Focus input and set cursor position at end
        var input =  $(component).find(inputSelector);
        var val = input.focus().val();
        input.val('').val(val);
      }
    });
  };

  $(document).on('input', inputSelector, _.debounce(executeSearch, 500));
});
