class ServerComponent extends HTMLElement {
  connectedCallback() {
    this.innerHTML = `
      <div class="spinkit-spinner primary-color">
        <div class="bounce1"></div>
        <div class="bounce2"></div>
        <div class="bounce3"></div>
      </div>
      <div class="server-html-content" ></div>
    `;

    let { cname, ...data } = [...this.attributes].reduce((obj, item) => {
      obj[item.name.replaceAll("-", "_")] = this.parseAttributeValue(item.value);
      return obj;
    }, {});

    this.load(cname, data);
  }

  async load(cname, data) {
    try {
      let html = await this.fetchHTML(cname, data);

      // we need to set innerHTML so MutationObserver's are working with the inserted DOM
      this.querySelector(".server-html-content").innerHTML = html;
    } catch (e) {
      this.innerHTML = `
        <div class="error">Daten konnten nicht geladen werden.</div>
      `;
    }

    this.querySelector(".spinkit-spinner").remove();
  }

  parseAttributeValue(str) {
    if (str.startsWith("{")) {
      return JSON.parse(str);
    }

    return str;
  }

  async fetchHTML(cname, data) {
    if (!cname) {
      throw new Error("cname attribute needs to be specified")
    }

    let params = $.param(data);
    let response = await fetch(`/components/${cname}?${params}`);
    if (response.ok) {
      return await response.text();
    }

    throw new Error(`could not load /components/${cname}`);
  }
}

customElements.define("server-component", ServerComponent);
$(document).ready(function() {
  function browserSupportsCSSProperty(propertyName) {
    var elm = document.createElement('div');
    propertyName = propertyName.toLowerCase();

    if (elm.style[propertyName] != undefined)
      return true;

    var propertyNameCapital = propertyName.charAt(0).toUpperCase() + propertyName.substr(1),
      domPrefixes = 'Webkit Moz ms O'.split(' ');

    for (var i = 0; i < domPrefixes.length; i++) {
      if (elm.style[domPrefixes[i] + propertyNameCapital] != undefined)
        return true;
    }

    return false;
  }

  if (!browserSupportsCSSProperty('animation')) {
    // Fallback
    $('.spinkit-spinner').html('Lade ...');
  }
});
