class XDialog extends HTMLElement {
  constructor() {
    super();

    this.addEventListener("click", this);
    this.addEventListener("x-dialog:closed", this, true);
    this.addEventListener("htmx:beforeRequest", this);
    this.addEventListener("htmx:afterRequest", this);
  }

  connectedCallback() {
    let dialog = this.querySelector("dialog");

    if (this.initialized || !dialog) {
      return;
    }

    this.initialized = true;

    if (this.dataset.resetOnClose === "true") {
      this.initialBodyHtml = dialog.querySelector(".modal-body").innerHTML;
    }

    dialog.addEventListener("close", () => {
      let skipResetOnClose = [...dialog.querySelectorAll("[data-skip-reset-on-close]")]
        .some((marker) => marker.closest("x-dialog") === this);

      if (this.dataset.resetOnClose === "true" && !skipResetOnClose) this.resetBody();
      this.dispatchEvent(new CustomEvent("x-dialog:closed", { bubbles: true }));
    });
    dialog.addEventListener("cancel", this);

    if (this.dataset.autoOpen === "true") {
      this.showModal();
    }
  }

  handleEvent(evt) {
    if (evt.type === "x-dialog:closed" && evt.target !== this) {
      evt.stopImmediatePropagation();
      return;
    }

    let dialog = this.querySelector("dialog");

    switch (evt.type) {
      case "click":
        if (evt.target.closest("x-dialog") === this && evt.target.closest("[data-action='dismiss']") && !this.busy) {
          dialog.close();
        }
        break;
      case "cancel":
        if (this.busy) evt.preventDefault();
        break;
      case "htmx:beforeRequest":
        if (evt.target.closest("x-dialog") === this && evt.target.closest("[data-lock-dialog]")) {
          this.busyRequest = evt.detail.xhr;
          this.setBusy(true);
        }
        break;
      case "htmx:afterRequest":
        if (this.busyRequest === evt.detail.xhr) {
          this.busyRequest = null;
          this.setBusy(false);
        }
        break;
    }
  }

  setBusy(busy) {
    if (this.busy === busy) return;

    let dialog = this.querySelector("dialog");

    if (busy && dialog) this.originalClosedby = dialog.getAttribute("closedby");

    this.busy = busy;
    this.toggleAttribute("data-busy", busy);
    dialog?.querySelectorAll("[data-action='dismiss']").forEach((button) => {
      if (button.closest("x-dialog") !== this) return;
      button.disabled = busy;
    });

    if (dialog) {
      if (busy) {
        dialog.setAttribute("closedby", "none");
      } else if (this.originalClosedby === null) {
        dialog.removeAttribute("closedby");
      } else {
        dialog.setAttribute("closedby", this.originalClosedby);
      }
    }
  }

  showModal() {
    let dialog = this.querySelector("dialog");

    if (dialog && !dialog.open) {
      dialog.showModal();
    }
  }

  resetBody() {
    let body = this.querySelector(".modal-body");

    if (body && this.initialBodyHtml) {
      body.innerHTML = this.initialBodyHtml;
      window.htmx?.process(body);
    }
  }
}

customElements.define("x-dialog", XDialog);
class XDialogTrigger extends HTMLElement {
  constructor() {
    super();

    this.addEventListener("click", this);
  }

  handleEvent(evt) {
    if (evt.defaultPrevented) {
      return;
    }

    let { dialogId } = this.dataset;
    let dialog = document.querySelector(
      `x-dialog[data-dialog-id='${dialogId}']`,
    );

    evt.preventDefault();
    dialog.showModal();
  }
}

customElements.define("x-dialog-trigger", XDialogTrigger);
class XCombobox extends HTMLElement {
  constructor() {
    super();
    this._handleClick = this.handleClick.bind(this);
    this._handleRemove = this.handleRemove.bind(this);
    this._handleDropDownClosed = this.handleDropDownClosed.bind(this);
    this._handleSelectEntityChange = this.handleSelectEntityChange.bind(this);
  }

  connectedCallback() {
    this.addEventListener("click", this._handleClick);

    this.removeButton = this.querySelector(".drop-down-trigger .remove");
    if (this.removeButton) {
      this.removeButton.addEventListener("click", this._handleRemove);
    }

    this.querySelector("drop-down").addEventListener("drop-down-closed", this._handleDropDownClosed);

    this.selectEntity = this.querySelector("select-entity");
    this.selectEntity.addEventListener("change", this._handleSelectEntityChange);
  }

  disconnectedCallback() {
    this.removeEventListener("click", this._handleClick);

    if (this.removeButton) {
      this.removeButton.removeEventListener("click", this._handleRemove);
    }

    this.querySelector("drop-down").removeEventListener("drop-down-closed", this._handleDropDownClosed);

    this.selectEntity.removeEventListener("change", this._handleSelectEntityChange);
  }

  handleClick(evt) {
    evt.preventDefault();

    if (evt.target.role === "option") {
      this._setSelected(evt.target.innerText, evt.target.dataset);
      this.querySelector("drop-down").close();
    }
  }

  handleRemove(evt) {
    evt.preventDefault();
    this._setSelected(this.dataset.placeholder, { value: null });
  }

  _setSelected(text, dataset) {
    this.querySelector(".selected-item").innerText = text;
    this.dataset.value = dataset.value ?? "";

    const inputField = this.querySelector("input.selected-value")
    if (inputField) {
      inputField.value = dataset.value;
      inputField.dispatchEvent(
        new CustomEvent("change", {
          bubbles: true,
          detail: { ...dataset, ...{ selectedText: text } }
        })
      );
    }
  }

  handleDropDownClosed(evt) {
    const selectEntity = evt.target.querySelector("select-entity");
    selectEntity.clearSearch();
  }

  handleSelectEntityChange(evt) {
    evt.stopPropagation();
  }
}

customElements.define("x-combobox", XCombobox);
$(document).ready(function() {
  $(document).on("show.bs.collapse", ".component.ui--accordion", function(e) {
    var paramsKey = e.currentTarget.dataset.paramsKey;
    if (paramsKey) {
      var selectedItemId = e.target.id;
      var url = URI().setSearch(paramsKey, selectedItemId).toString();
      history.replaceState(null, null, url);
    }
  });
});
document.addEventListener("DOMContentLoaded", function() {
  $('[data-toggle="tooltip"]').tooltip();
});

document.body.addEventListener("htmx:afterSwap", function(event){
  $('[data-toggle="tooltip"]', event.target).tooltip();
});
$(document).ready(function() {
  $(".status-dot[data-toggle='tooltip']").tooltip({ trigger: "hover" });
});
var Skizeit = Skizeit || {};
Skizeit.Charting = Skizeit.Charting || {};

Skizeit.Charting.SuccessesChart = function(options){
  var colors = {
    1: '#d8b868',
    2: '#c0c0c0',
    3: '#b87333',
    4: '#006699',
    5: '#0d233a'
  };

  this.options = {
    chart: { type: 'column' },
    credits: { enabled: false },
    plotOptions: {
      column: {
          stacking: 'normal',
          dataLabels: {
              enabled: true,
              color: 'white',
              formatter: function() {
                return this.y > 0 ? this.y : null;
              }
          }
      }
    },
    title: { text: 'Top 5 Platzierungen' },
    subtitle: { },
    xAxis: {},
    yAxis: {
      allowDecimals: false,
      stackLabels: {
          enabled: true,
          style: {
              fontWeight: 'bold',
              color: 'gray'
          }
      },
      title: { text: 'Anzahl Top 5 Platzierungen' }
    }
  };

  this.categories = function(data){
    return $.map(data, function(val, key){
      return key;
    });
  };

  this.series = function(data){
    var positions = [1, 2, 3, 4, 5];
    var series = [{}, {}, {}, {}, {}];
    $.each(positions, function(i, pos){
      series[pos - 1].name = pos + '. Ränge';
      series[pos - 1].data = [];
      series[pos - 1].color = colors[pos];
      $.each(data, function(season, data){
        series[pos - 1].data.push(data[pos] || 0);
      });
    });
    return series;
  };

  this.options.chart.renderTo = options.renderTo;
  this.options.subtitle.text = options.subtitle;
  this.options.xAxis.categories = this.categories(options.data);
  this.options.series = this.series(options.data);

  new Highcharts.Chart(this.options);
};
