const TOOLTIP_DURATION_ms = 1000;

class ClipboardAction extends HTMLElement {
  connectedCallback() {
    this.clipboardActionEl = this.querySelector(".clipboard-action");

    this.tooltipEl = $(this.clipboardActionEl).tooltip({
      title: "In Zwischenablage kopiert",
      trigger: "manual",
    });

    this.addEventListener("click", this);
  }

  async handleEvent() {
    let { clipboardText, clipboardTextUrl } = this.clipboardActionEl.dataset;
    let text;

    if (clipboardTextUrl) {
      let res = await fetch(clipboardTextUrl);
      text = await res.text();
    } else {
      text = clipboardText;
    }

    await navigator.clipboard.writeText(text);

    clearTimeout(this.timeout);

    this.tooltipEl.tooltip("show");

    this.timeout = setTimeout(() => {
      this.tooltipEl.tooltip("hide");
    }, TOOLTIP_DURATION_ms);
  }
}

customElements.define("clipboard-action", ClipboardAction);
